-- 백엔드 요구 기술 13개 중 Java·SQL·MySQL·Git·Spring Boot·Python을 가진 상태에서 시작 —
-- Docker·REST API·DNS 등 빈 칸이 격차 분석과 로드맵에 드러난다
INSERT INTO USER_SKILLS (user_id, skill_id, raw_input, similarity_score, proficiency)
SELECT @demo, s.id, v.raw_input, v.sim, v.prof
FROM SKILL s JOIN (
    SELECT 'Java' AS name, 'Java' AS raw_input, 1.0000 AS sim, 'ADVANCED' AS prof UNION ALL
    SELECT 'Spring Boot', '스프링부트', 0.9412, 'INTERMEDIATE' UNION ALL
    SELECT 'SQL', 'SQL', 1.0000, 'INTERMEDIATE' UNION ALL
    SELECT 'MySQL', 'mysql', 1.0000, 'INTERMEDIATE' UNION ALL
    SELECT 'Git', 'Git', 1.0000, 'INTERMEDIATE' UNION ALL
    SELECT 'Python', '파이썬', 0.9137, 'BEGINNER' UNION ALL
    SELECT 'JavaScript', 'JavaScript', 1.0000, 'BEGINNER' UNION ALL
    SELECT 'Linux', '리눅스', 0.9254, 'BEGINNER'
) v ON v.name = s.skill_name
WHERE s.is_deleted = FALSE;

INSERT INTO USER_SKILLS (user_id, skill_id, raw_input, similarity_score, proficiency)
SELECT u.id, s.id, s.skill_name, 1.0000, v.prof
FROM USERS u JOIN (
    SELECT 'demo_peer_1' AS login_id, 'Java' AS name, 'INTERMEDIATE' AS prof UNION ALL
    SELECT 'demo_peer_1', 'Spring Boot', 'INTERMEDIATE' UNION ALL
    SELECT 'demo_peer_1', 'MySQL', 'BEGINNER' UNION ALL
    SELECT 'demo_peer_1', 'Docker', 'INTERMEDIATE' UNION ALL
    SELECT 'demo_peer_1', 'Git', 'INTERMEDIATE' UNION ALL
    SELECT 'demo_peer_1', 'AWS', 'BEGINNER' UNION ALL
    SELECT 'demo_peer_2', 'Python', 'ADVANCED' UNION ALL
    SELECT 'demo_peer_2', 'Java', 'BEGINNER' UNION ALL
    SELECT 'demo_peer_2', 'SQL', 'INTERMEDIATE' UNION ALL
    SELECT 'demo_peer_2', 'Git', 'BEGINNER' UNION ALL
    SELECT 'demo_peer_2', 'PostgreSQL', 'INTERMEDIATE'
) v ON v.login_id = u.login_id
JOIN SKILL s ON s.skill_name = v.name AND s.is_deleted = FALSE;

