INSERT INTO USER_SURVEY_ANSWER (user_id, question_id, answer_value, answered_at)
SELECT @demo, q.id,
       CASE q.job_category_hint WHEN 'BACKEND' THEN 5 WHEN 'DEVOPS' THEN 4 WHEN 'DATA' THEN 4
                                WHEN 'SECURITY' THEN 3 WHEN 'FRONTEND' THEN 2 ELSE 2 END,
       NOW() - INTERVAL 100 DAY
FROM SURVEY_QUESTION q
WHERE q.survey_type = 'JOB_DISCOVERY' AND q.is_deleted = FALSE;

INSERT INTO JOB_RECOMMENDATION (user_id, job_id, rank_order, match_reason, is_selected, created_at)
SELECT @demo, j.id, v.rank_order, v.reason, v.rank_order = 1, NOW() - INTERVAL 100 DAY
FROM JOB j JOIN (
    SELECT '백엔드 개발자' AS job_name, 1 AS rank_order,
           '설문에서 서버·로직 관련 문항에 평균 5.0점(5점 만점)으로 답했고, 보유 기술 Java·Spring Boot·MySQL·SQL·Git이 이 직무 필수 기술과 겹칩니다.' AS reason UNION ALL
    SELECT 'DevOps 엔지니어', 2, '설문에서 운영·자동화 관련 문항에 평균 4.0점으로 답했고, Linux·Git 경험이 배포 자동화로 이어질 수 있습니다.' UNION ALL
    SELECT '데이터 엔지니어', 3, '설문에서 데이터 정리·분석 관련 문항에 평균 4.0점으로 답했고, SQL·Python과 SQLD 자격이 데이터 파이프라인 업무와 맞닿아 있습니다.' UNION ALL
    SELECT '서버 개발자', 4, '백엔드 개발자와 요구 기술이 많이 겹쳐 함께 준비하기 좋은 직무입니다.' UNION ALL
    SELECT '정보보안 담당자', 5, '설문에서 보안 관련 문항에 평균 3.0점으로 답했습니다. 관심이 생기면 정보보안기사부터 시작해 볼 수 있습니다.'
