INSERT INTO EVALUATION_CRITERIA (session_id, skill_id, weight)
SELECT @session, s.id, v.weight
FROM SKILL s JOIN (
    SELECT 'Java' AS name, 3 AS weight UNION ALL
    SELECT 'Spring Boot', 3 UNION ALL
    SELECT 'MySQL', 2 UNION ALL
    SELECT 'Docker', 2 UNION ALL
    SELECT 'Git', 1
) v ON v.name = s.skill_name AND s.is_deleted = FALSE;

