INSERT INTO TECH_ARTICLE (user_id, skill_id, source_type, title, content, status, published_at,
                          view_count, like_count, comment_count, bookmark_count, created_at) VALUES
    (@demo, (SELECT id FROM SKILL WHERE skill_name = 'MySQL' LIMIT 1), 'ARCHIVE_TIP',
     '목록 조회 820ms → 140ms, 복합 인덱스 하나로 줄인 이야기',
     '중고거래 API의 상품 목록이 느려서 실행 계획부터 봤습니다.\n\n```sql\nEXPLAIN SELECT * FROM product\nWHERE category_id = ? ORDER BY created_at DESC LIMIT 20;\n```\n\ntype이 ALL(전체 스캔)이었고, 정렬도 filesort였습니다.\n\n```sql\nCREATE INDEX idx_product_category_created ON product (category_id, created_at);\n```\n\n인덱스를 건 뒤 OFFSET 대신 마지막으로 본 created_at을 기준으로 다음 페이지를 가져오는 커서 방식으로 바꿨습니다.\n\n- 인덱스 컬럼 순서: 같다(=) 조건 → 정렬 컬럼\n- OFFSET이 커질수록 느려지는 문제는 커서로 해결\n\n결과적으로 평균 응답이 820ms에서 140ms로 줄었습니다.',
     'PUBLISHED', NOW() - INTERVAL 9 DAY, 48, 0, 1, 0, NOW() - INTERVAL 9 DAY),
    (@demo, NULL, 'ARCHIVE_TIP',
     '정보처리기사 실기, 3주 만에 붙은 공부 순서',
     '실기는 범위가 넓어서 순서가 중요했습니다.\n\n1. 1주차: SQL·자료구조 — 배점이 크고 점수가 안정적\n2. 2주차: 프로그래밍 언어(Java·C·Python) 출력 결과 문제 — 매일 10문제\n3. 3주차: 기출 5회분 시간 재고 풀기\n\n스펙 오디세이 로드맵에서 SQL 단계를 먼저 끝낸 게 실기 SQL 문제에 그대로 도움이 됐습니다.',
     'PUBLISHED', NOW() - INTERVAL 20 DAY, 73, 0, 0, 0, NOW() - INTERVAL 20 DAY);
SET @article := (SELECT id FROM TECH_ARTICLE WHERE user_id = @demo AND title LIKE '목록 조회 820ms%');

